// Builds words.js: a compact Bloom filter of English words for Sentence Fix grading.
// Usage: node vendor/english-words/build.mjs path/to/enable1.txt
// Words: the ENABLE word list (public domain, see README.md) plus every word in the answer keys of
// data/sentence-fix/bank.json (names such as "Diego"). A Bloom filter never misses a listed word; about 1 in 100
// unlisted strings is wrongly reported as a word, which only makes grading more cautious (review, not incorrect).
import { readFileSync, writeFileSync } from 'node:fs';

const [, , enablePath] = process.argv;
if (!enablePath) throw new Error('usage: node vendor/english-words/build.mjs path/to/enable1.txt');
const words = new Set(readFileSync(enablePath, 'utf8').split(/\r?\n/).map((w) => w.trim().toLowerCase()).filter(Boolean));
const bank = JSON.parse(readFileSync(new URL('../../data/sentence-fix/bank.json', import.meta.url), 'utf8'));
for (const it of bank.items) {
  for (const key of [it.correct, ...(it.accepted || [])]) {
    for (const w of String(key).toLowerCase().match(/\p{L}+/gu) || []) words.add(w);
  }
}

const BITS_PER_WORD = 10, K = 7;
const M = Math.ceil((words.size * BITS_PER_WORD) / 8) * 8;
const fnv = (s, seed) => {
  let h = seed;
  for (const ch of s) { h ^= ch.codePointAt(0); h = Math.imul(h, 0x01000193); }
  return h >>> 0;
};
const bits = new Uint8Array(M / 8);
for (const w of words) {
  const h1 = fnv(w, 0x811c9dc5), h2 = fnv(w, 0x050c5d1f) | 1;
  for (let i = 0; i < K; i++) { const b = (h1 + Math.imul(i, h2) >>> 0) % M; bits[b >> 3] |= 1 << (b & 7); }
}
const out = `// Generated by vendor/english-words/build.mjs. Do not edit by hand. See vendor/english-words/README.md.
// Bloom filter of ${words.size} English words (ENABLE word list, public domain, plus the Sentence Fix answer-key words).
export const WORD_FILTER = { m: ${M}, k: ${K}, bits: '${Buffer.from(bits).toString('base64')}' };
`;
writeFileSync(new URL('./words.js', import.meta.url), out);
console.log(`${words.size} words, ${M} bits, ${out.length} bytes`);
